L = lesson(ch, "enquiry", "Geographical enquiry: sampling, statistics and Spearman’s rank",
    ["Plan a geographical investigation", "Choose suitable sampling and data-collection methods", "Calculate and interpret Spearman’s rank correlation coefficient"],
    [("methode", "Enquiry process", "1. Question or hypothesis. 2. Methods: questionnaires, measurements, counts, interviews, secondary data. 3. **Sampling** (random, systematic, stratified). 4. Risk assessment and ethics. 5. Presentation (graphs, maps, tables). 6. Analysis with statistics. 7. Conclusion and evaluation of reliability and bias."),
     ("formule", "Spearman’s rank", "Rank both variables, find the difference d between ranks for each pair, then $r_s = 1 - \\frac{6 \\sum d^2}{n(n^2 - 1)}$. A value near +1 shows strong positive correlation, near −1 strong negative, near 0 none. Compare with a critical value to test significance (given in tables).", "r_s = 1 - \\frac{6 \\sum d^2}{n(n^2 - 1)}"),
     ("attention", "Interpreting results", "A strong correlation does not prove one variable causes the other. Small samples may be unreliable, and a fieldwork site may not represent the whole area. Always comment on the limits and suggest improvements.")],
    [("Example 1 — Calculate", "Five towns are ranked by size (x) and by number of services (y). Ranks of the pairs (x, y) are (1,2), (2,1), (3,4), (4,3), (5,5). Calculate Spearman’s r_s.",
      ["d = x − y: −1, 1, −1, 1, 0.", "d² = 1, 1, 1, 1, 0; Σd² = 4.", "r_s = 1 − 6 × 4 ÷ (5 × 24) = 1 − 24 ÷ 120 = 0.8."], "r_s = 0.8: strong positive correlation."),
     ("Example 2 — Choose sampling", "A student surveys a 400-house district divided into four equal neighbourhoods. She needs 40 houses. Name an unbiased method.",
      ["Stratified: sample proportionally from each neighbourhood.", "10 houses per neighbourhood, chosen at random from each list."], "Stratified random sampling (10 per neighbourhood).")],
    [N("Σd² = 6 and n = 5. Calculate r_s (3 d.p.).", 0.7, "r_s = 1 − (6 × 6) ÷ (5 × 24) = 1 − 36 ÷ 120 = 0.7.", 0.001),
     M("An r_s value of −0.9 shows", "A strong negative correlation", ["A strong positive correlation", "No correlation", "An error"], "Close to −1."),
     TF("A strong correlation proves that one variable causes the other.", False, "Correlation is not causation."),
     N("Five pairs have Σd² = 0. What is r_s?", 1, "r_s = 1 − 0 = 1: perfect agreement of ranks.", 0.001),
     M("Systematic sampling means", "Taking every nth item from a list", ["Choosing by chance each time", "Choosing only convenient places", "Taking all items"], "Regular interval."),
     P("A student collects data on distance from the town centre and house price. After ranking, Σd² = 12 for n = 6 pairs (illustrative).", [pn("Calculate r_s to 2 d.p.", 0.66, "r_s = 1 − 6 × 12 ÷ (6 × 35) = 1 − 72 ÷ 210 = 0.657, about 0.66.", 0.01, 2), pm("What does this show?", "A fairly strong positive relationship between the ranks", ["No relationship", "A strong negative relationship", "A perfect relationship"], "0.66 is positive and moderately strong.", 1), po("State one limitation of using only six pairs.", "A small sample may not be representative and the result may be due to chance, so the relationship cannot be generalised.", "One valid limitation (1) with reason (1).", 2)])],
    [("Spearman’s r_s ranges from", "−1 to +1", ["0 to 100", "−10 to +10", "0 to 1000"], "Definition."),
     ("Stratified sampling ensures", "Subgroups are represented in proportion", ["Only random selection", "Only big groups are chosen", "No groups are sampled"], "Proportional representation."),
     ("A questionnaire gives", "Primary data", ["Secondary data only", "Satellite data", "No data"], "Collected first-hand."),
     ("A risk assessment is done to", "Identify and reduce hazards in fieldwork", ["Choose a topic", "Draw graphs", "Mark papers"], "Safety first."),
     ("An r_s near 0 suggests", "No clear relationship", ["Perfect agreement", "Strong negative link", "Strong positive link"], "Weak or no correlation.")],
    (flow(["Question and hypothesis", "Methods and sampling", "Collect and present data", "Analyse, conclude, evaluate"], 440, "blue", 13, 300), "The stages of a geographical enquiry.", "Four boxes: question, methods and sampling, collect and present, analyse conclude evaluate."),
    ["Check whether the syllabus tests Spearman’s rank with significance tables, chi-squared or standard deviation.", "All data are illustrative."])
# assertion checks of numbers
assert round(1 - 6*4/(5*24), 3) == 0.8 and round(1 - 36/120, 3) == 0.7 and round(1 - 72/210, 2) == 0.66

